// uLipSync calibration against the characters' RUNTIME voices (Play mode).
//   unity command script eval -- --file AgentScripts/LipSyncCalibrate.cs --timeout 300
// 1. Phonemes: sustained vowel clips in each voice (Backend/medsim-proxy/data/lipsync/<voice>_<A|I|U|E|O|N>.wav, generated by
//    tools/make-vowel-audio.mjs) are played through the character's own AudioSource; the steadiest held-vowel window is used
//    and uLipSync.RequestCalibration stores those MFCCs in project copies of the profiles (Assets/MedSimAI/Characters/v2/LipSync).
// 2. Loudness: real reply sentences in the same voices (data/voice-out) give the voiced log-volume range per character.
// Writes Screenshots/Polish/lipsync_calibration.txt (volume range is applied to the scene afterwards in Edit mode).
using UnityEngine; using UnityEditor; using System; using System.IO; using System.Linq; using System.Threading.Tasks; using System.Collections.Generic;
using MedSimAI.AI; using MedSimAI.Characters; using MedSimAI.Voice;
string data = "D:/Medical-Test/My project/Backend/medsim-proxy/data/";
string outDir = "Assets/MedSimAI/Characters/v2/LipSync/"; if (!AssetDatabase.IsValidFolder(outDir.TrimEnd('/'))) AssetDatabase.CreateFolder("Assets/MedSimAI/Characters/v2", "LipSync");
var log = new List<string>();
async Task W(float s) { float t = Time.realtimeSinceStartup + s; while (Time.realtimeSinceStartup < t) await Task.Yield(); }
float[] Wav(string path) { var b = File.ReadAllBytes(path); int n = (b.Length - 44) / 2; var f = new float[n]; for (int i = 0; i < n; i++) f[i] = (short)(b[44 + 2 * i] | (b[45 + 2 * i] << 8)) / 32768f; return f; }
// steadiest voiced window (~1.4 s) — skips any extra words the voice actor added
float[] Steady(float[] s, float seconds = 1.4f)
{
  int fr = 480, n = s.Length / fr; var rms = new float[n]; for (int i = 0; i < n; i++) { float q = 0; for (int k = 0; k < fr; k++) q += s[i * fr + k] * s[i * fr + k]; rms[i] = Mathf.Sqrt(q / fr); }
  int win = Mathf.Min(n, (int)(seconds * 50)); float best = float.MaxValue; int at = 0; float peak = rms.Max();
  for (int i = 0; i + win <= n; i++) { float mean = 0; for (int k = 0; k < win; k++) mean += rms[i + k]; mean /= win; if (mean < peak * 0.25f) continue; float v = 0; for (int k = 0; k < win; k++) v += (rms[i + k] - mean) * (rms[i + k] - mean); v = Mathf.Sqrt(v / win) / mean; if (v < best) { best = v; at = i; } }
  var o = new float[win * fr]; Array.Copy(s, at * fr, o, 0, o.Length); return o;
}
var V = VoiceInteractionManager.Instance; V.Interrupt();
var results = new Dictionary<string, (float min, float max)>();
foreach (var (persona, voice, srcProfile) in new[] { (Persona.Patient, "cedar", "Male"), (Persona.Instructor, "marin", "Female") })
{
  var sp = UnityEngine.Object.FindObjectsByType<CharacterSpeechController>(FindObjectsSortMode.None).First(c => c.persona == persona);
  var lip = sp.GetComponent<uLipSync.uLipSync>(); var src = sp.GetComponent<AudioSource>();
  string dst = outDir + (persona == Persona.Patient ? "Patient_cedar" : "Doctor_marin") + ".asset";
  if (!File.Exists(dst)) AssetDatabase.CopyAsset("Packages/com.hecomi.ulipsync/Assets/Profiles/uLipSync-Profile-Sample-" + srcProfile + ".asset", dst);
  var prof = AssetDatabase.LoadAssetAtPath<uLipSync.Profile>(dst); lip.profile = prof;
  await W(0.3f);
  for (int i = 0; i < prof.mfccs.Count; i++)
  {
    var ph = prof.GetPhoneme(i); var f = data + "lipsync/" + voice + "_" + ph + ".wav"; if (!File.Exists(f)) { log.Add($"{voice} {ph}: no clip (kept sample data)"); continue; }
    var seg = Steady(Wav(f)); var clip = AudioClip.Create("calib_" + voice + ph, seg.Length, 1, 24000, false); clip.SetData(seg, 0);
    sp.Stop(); src.clip = clip; src.loop = true; src.Play(); await W(0.25f);
    int n = 0; float until = Time.realtimeSinceStartup + 1.6f;
    while (Time.realtimeSinceStartup < until) { if (lip.result.rawVolume > 1e-3f) { lip.RequestCalibration(i); n++; } await W(0.06f); }
    src.Stop(); src.loop = false; UnityEngine.Object.Destroy(clip);
    log.Add($"{voice} phoneme {ph}: {n} calibration frames from a {seg.Length / 24000f:0.0}s steady window");
  }
  prof.UpdateMeansAndStandardization(); EditorUtility.SetDirty(prof);
  // loudness range from real sentences in this voice
  var vols = new List<float>();
  foreach (var f in Directory.GetFiles(data + "voice-out", (persona == Persona.Patient ? "patient_" : "doctor_") + "*.wav"))
  {
    var s = Wav(f); var clip = AudioClip.Create("vol", s.Length, 1, 24000, false); clip.SetData(s, 0);
    src.clip = clip; src.Play(); float end = Time.realtimeSinceStartup + Mathf.Min(clip.length, 6f);
    while (Time.realtimeSinceStartup < end) { var rv = lip.result.rawVolume; if (rv > 1e-4f) vols.Add(Mathf.Log10(rv)); await Task.Yield(); }
    src.Stop(); UnityEngine.Object.Destroy(clip);
  }
  vols.Sort(); float P(float q) => vols.Count == 0 ? 0 : vols[Mathf.Clamp((int)(q * vols.Count), 0, vols.Count - 1)];
  float lo = P(0.20f), hi = P(0.97f); results[persona.ToString()] = (lo, hi);
  log.Add($"{voice} loudness: {vols.Count} voiced frames, log10 volume p20={lo:0.00} p50={P(0.5f):0.00} p97={hi:0.00} (uLipSync default range -2.5..-1.5)");
}
AssetDatabase.SaveAssets();
File.WriteAllLines("D:/Medical-Test/My project/Screenshots/Polish/lipsync_calibration.txt", log.Concat(results.Select(kv => $"RANGE {kv.Key} {kv.Value.min:0.000} {kv.Value.max:0.000}")));
return string.Join("\n", log);
